-- Generated by npm run db:schema. Structure/defaults only; no owner, sessions or business/demo data.
-- Preferred import: INITIALIZE_EMPTY_DATABASE=true on first Coolify launch.
-- Manual import requires private session settings skladno.expected_database and skladno.expected_role.
BEGIN;
SELECT pg_advisory_xact_lock(72904110);
SET LOCAL search_path=public,pg_catalog;
DO $guard$
BEGIN
  IF current_setting('skladno.expected_database',true) IS NULL OR current_setting('skladno.expected_role',true) IS NULL
    OR current_database()<>current_setting('skladno.expected_database',true) OR current_user<>current_setting('skladno.expected_role',true) THEN
    RAISE EXCEPTION 'DATABASE_IDENTITY_NOT_CONFIRMED';
  END IF;
  IF (SELECT
    (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
     WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'
       AND c.relkind IN ('r','p','v','m','S','f')
       AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e'))+
    (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'
       AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')) AS count)<>0 THEN RAISE EXCEPTION 'DATABASE_NOT_EMPTY'; END IF;
END $guard$;
CREATE TABLE schema_migrations(name text PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());

-- 001_auth.sql
CREATE TABLE owner_account (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  id uuid NOT NULL UNIQUE,
  password_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  password_changed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE owner_sessions (
  token_hash text PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES owner_account(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX owner_sessions_expiry ON owner_sessions(expires_at);
CREATE TABLE auth_throttle (
  key_hash text PRIMARY KEY,
  attempts integer NOT NULL DEFAULT 0,
  window_start timestamptz NOT NULL DEFAULT now()
);

