-- 002_rentals.sql
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE clients (
  id uuid PRIMARY KEY, name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '',
  archived_at timestamptz, version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE warehouses (
  id uuid PRIMARY KEY, number text NOT NULL CHECK (length(trim(number)) BETWEEN 1 AND 80),
  number_key text NOT NULL UNIQUE, area numeric(12,2) CHECK (area > 0), address text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '',
  availability text NOT NULL DEFAULT 'available' CHECK (availability IN ('available','maintenance')),
  archived_at timestamptz, version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE leases (
  id uuid PRIMARY KEY, client_id uuid NOT NULL REFERENCES clients(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id),
  start_date date NOT NULL, end_date date, notes text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (end_date IS NULL OR end_date > start_date),
  CONSTRAINT no_overlapping_leases EXCLUDE USING gist
    (warehouse_id WITH =, daterange(start_date,end_date,'[)') WITH &&)
);
CREATE INDEX leases_client ON leases(client_id);
CREATE TABLE lease_rate_versions (
  id uuid PRIMARY KEY, lease_id uuid NOT NULL REFERENCES leases(id), effective_date date NOT NULL,
  monthly_amount_minor bigint NOT NULL CHECK (monthly_amount_minor BETWEEN 1 AND 1000000000000),
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lease_id,effective_date)
);
CREATE TABLE charges (
  id uuid PRIMARY KEY, lease_id uuid NOT NULL REFERENCES leases(id), period_index integer NOT NULL CHECK(period_index >= 0),
  period_start date NOT NULL, period_end date NOT NULL, due_date date NOT NULL,
  amount_minor bigint NOT NULL CHECK(amount_minor BETWEEN 1 AND 1000000000000),
  cancelled_at timestamptz, cancel_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(period_end > period_start), UNIQUE(lease_id,period_index), UNIQUE(id,lease_id)
);
CREATE INDEX charges_open_due ON charges(due_date) WHERE cancelled_at IS NULL;
CREATE TABLE payments (
  id uuid PRIMARY KEY, lease_id uuid NOT NULL REFERENCES leases(id), received_on date NOT NULL,
  amount_minor bigint NOT NULL CHECK(amount_minor BETWEEN 1 AND 1000000000000),
  method text NOT NULL CHECK(method IN ('cash','transfer','other')), notes text NOT NULL DEFAULT '',
  idempotency_key uuid NOT NULL UNIQUE, request_hash text NOT NULL,
  reversed_at timestamptz, reversal_reason text,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,lease_id)
);
CREATE INDEX payments_received ON payments(received_on);
CREATE INDEX payments_lease ON payments(lease_id);
CREATE TABLE payment_allocations (
  id uuid PRIMARY KEY, lease_id uuid NOT NULL, payment_id uuid NOT NULL, charge_id uuid NOT NULL,
  amount_minor bigint NOT NULL CHECK(amount_minor > 0),
  FOREIGN KEY(payment_id,lease_id) REFERENCES payments(id,lease_id),
  FOREIGN KEY(charge_id,lease_id) REFERENCES charges(id,lease_id), UNIQUE(payment_id,charge_id)
);
CREATE INDEX payment_allocations_charge ON payment_allocations(charge_id);
CREATE TABLE payment_reversals (
  payment_id uuid PRIMARY KEY REFERENCES payments(id), reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION check_allocation_limits() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE charge_limit bigint; payment_limit bigint; charge_paid numeric; payment_used numeric;
BEGIN
  SELECT amount_minor INTO charge_limit FROM charges WHERE id=NEW.charge_id AND cancelled_at IS NULL FOR UPDATE;
  IF charge_limit IS NULL THEN RAISE EXCEPTION 'CHARGE_NOT_AVAILABLE' USING ERRCODE='23514'; END IF;
  SELECT amount_minor INTO payment_limit FROM payments WHERE id=NEW.payment_id FOR UPDATE;
  SELECT COALESCE(sum(a.amount_minor),0) INTO charge_paid FROM payment_allocations a JOIN payments p ON p.id=a.payment_id
    WHERE a.charge_id=NEW.charge_id AND p.reversed_at IS NULL;
  SELECT COALESCE(sum(amount_minor),0) INTO payment_used FROM payment_allocations WHERE payment_id=NEW.payment_id;
  IF charge_paid > charge_limit OR payment_used > payment_limit THEN
    RAISE EXCEPTION 'ALLOCATION_LIMIT' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER allocation_limits AFTER INSERT OR UPDATE ON payment_allocations
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_allocation_limits();
CREATE TABLE app_settings (
  singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
  business_name text NOT NULL DEFAULT 'Складно', timezone text NOT NULL DEFAULT 'Europe/Moscow',
  reminder_days integer NOT NULL DEFAULT 5 CHECK(reminder_days BETWEEN 0 AND 90),
  reminder_time text NOT NULL DEFAULT '09:00', telegram_enabled boolean NOT NULL DEFAULT false,
  telegram_chat_id text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1,
  scheduler_last_run_at timestamptz
);
INSERT INTO app_settings(singleton) VALUES(true);
CREATE TABLE notification_jobs (
  id uuid PRIMARY KEY, lease_id uuid NOT NULL REFERENCES leases(id), charge_id uuid NOT NULL REFERENCES charges(id),
  scheduled_on date NOT NULL, rule_days integer NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed','uncertain','cancelled')),
  attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz,
  sent_at timestamptz, message_id text, result_code text,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(charge_id,scheduled_on,rule_days)
);
CREATE INDEX notification_jobs_queue ON notification_jobs(next_attempt_at) WHERE status='pending';
CREATE TABLE notification_events (
  id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES notification_jobs(id), result_code text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE audit_events (
  id uuid PRIMARY KEY, entity_type text NOT NULL, entity_id uuid, action text NOT NULL,
  detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);

